package cn.sifangguan.hotelaios.finance;

import org.apache.poi.xssf.usermodel.*;
import org.apache.poi.ss.usermodel.*;
import org.openxmlformats.schemas.spreadsheetml.x2006.main.STCellType;
import org.apache.fontbox.ttf.*;
import org.apache.pdfbox.pdmodel.*;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.font.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import java.io.*;
import java.math.BigDecimal;
import java.nio.file.*;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Exports precisely the already authorized frozen result, not a second query. */
final class FinanceInsightExportRenderer {
 private FinanceInsightExportRenderer(){}
 private static final Map<String,String> SECTIONS=Map.of("facts","经营事实与完整性","budgetExecution","当前登记预算控制（非历史月末）","cashPlanControls","受控资金计划（非全部银行现金）","aging","月末往来账龄","channels","渠道收入","cashPlan","资金需求","revenueReconciliation","营业收入调节","analysis","模型分析（非业务事实）","recommendations","建议、假设与不确定性");
 private static final Set<String> MONEY=Set.of("pmsNetRevenue","postedExpense","postedNetProfit","registeredCashIn","registeredCashOut","registeredCashNet","inventoryValue","revenue","expense","netProfit","assets","liabilities","equity","unclosedProfit","beginningCash","endingCash","netMovement","OPERATING","INVESTING","FINANCING","TRANSFER","UNCLASSIFIED","value","currentAmount","comparisonAmount","absoluteChange","observedAmount","amount","committed","inflight","actual","remainingAmount","grossAmount","netAmount","taxAmount","commission","fee","sourceNetRevenue","postedRevenue","difference");
 static byte[] render(Map<String,Object> data,String format){if(!Set.of("xlsx","pdf").contains(format))throw bad("导出格式仅支持xlsx或pdf");try{return format.equals("xlsx")?excel(data):pdf(data);}catch(ResponseStatusException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"经营报表导出未完成，请核对字体或金额精度；未替换成其他格式",e);}}
 private static List<Map.Entry<String,List<Map<String,Object>>>> sections(Map<String,Object> data){var result=new ArrayList<Map.Entry<String,List<Map<String,Object>>>>();if("DAY".equals(data.get("periodKind"))){result.add(Map.entry("当日单店经营快报",rows(data.get("dailyOperating"))));result.add(Map.entry("当日集团管理汇总",rows(data.get("dailyGroup"))));result.add(Map.entry("当日收款与现金日报",rows(data.get("dailyCash"))));}for(String key:List.of("facts","budgetExecution","cashPlanControls","aging","channels","cashPlan","revenueReconciliation","analysis","recommendations"))result.add(Map.entry(SECTIONS.get(key),data.get(key)==null?List.of():rows(data.get(key))));result.add(Map.entry("真实预算业务来源",rows(data.getOrDefault("budgetBusinessSources",List.of()))));result.add(Map.entry("预算来源待核对问题",rows(data.getOrDefault("budgetSourceIssues",List.of()))));for(String key:List.of("incomeStatement","balanceSheet","cashFlowStatement")){var statements=new ArrayList<Map<String,Object>>();for(var book:rows(data.getOrDefault("books",List.of()))){var row=new LinkedHashMap<String,Object>();for(String field:List.of("bookId","hotelId","companyId","hotelName","reportVersion","status"))row.put(field,book.get(field));for(var entry:map(book.get(key)).entrySet())if(!entry.getKey().equals("lines")){if(entry.getKey().equals("categories"))map(entry.getValue()).forEach((category,amount)->row.put(category,amount));else row.put(entry.getKey(),entry.getValue());}statements.add(row);}result.add(Map.entry(switch(key){case "incomeStatement"->"同源利润表汇总";case "balanceSheet"->"同源资产负债表汇总";default->"同源现金流量表汇总";},statements));}return result;}
 private static byte[] excel(Map<String,Object> data)throws IOException{try(var workbook=new XSSFWorkbook();var out=new ByteArrayOutputStream()){var metadata=workbook.createSheet("口径与冻结版本");int n=0;for(String key:List.of("reportVersion","periodKind","date","month","status","currency","amountUnit","dateBasis","groupBasis","generatedAt","analysisVersion","analysisStatus","analysisTitle","model")){var row=metadata.createRow(n++);row.createCell(0).setCellValue(key);row.createCell(1).setCellValue(Objects.toString(data.get(key),""));}metadata.setColumnWidth(0,28*256);metadata.setColumnWidth(1,95*256);var style=workbook.createCellStyle();style.setDataFormat(workbook.createDataFormat().getFormat("#,##0.00;[Red](#,##0.00)"));for(var section:sections(data)){var sheet=workbook.createSheet(section.getKey());var keys=new LinkedHashSet<String>();section.getValue().forEach(r->keys.addAll(r.keySet()));var header=new ArrayList<>(keys);var heading=sheet.createRow(0);for(int c=0;c<header.size();c++){heading.createCell(c).setCellValue(header.get(c));sheet.setColumnWidth(c,25*256);}int index=1;for(var source:section.getValue()){var row=sheet.createRow(index++);for(int c=0;c<header.size();c++){String key=header.get(c);Object value=source.get(key);var cell=row.createCell(c);if(value!=null&&MONEY.contains(key)){BigDecimal decimal=amount(value);if(decimal.stripTrailingZeros().precision()>15)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"金额超过Excel数值精度，请导出PDF核对精确金额");cell.getCTCell().setT(STCellType.N);cell.getCTCell().setV(decimal.toPlainString());cell.setCellStyle(style);}else cell.setCellValue(value==null?"资料不足 / 不适用":Objects.toString(value));}}sheet.createFreezePane(0,1);}workbook.getProperties().getCoreProperties().setDescription("reportVersion="+data.get("reportVersion"));workbook.write(out);return out.toByteArray();}}
 private record Font(PDFont value,TrueTypeCollection collection)implements AutoCloseable{public void close()throws IOException{if(collection!=null)collection.close();}}
 private static Font font(PDDocument document)throws IOException{var paths=new ArrayList<String>();String configured=System.getProperty("hotel.ai.os.pdf.font.sans.path","");if(!configured.isBlank())paths.add(configured);paths.addAll(List.of("C:/Windows/Fonts/simhei.ttf","C:/Windows/Fonts/msyh.ttc","/usr/share/fonts/truetype/wqy/wqy-zenhei.ttc","/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc"));for(String path:paths){if(!Files.isRegularFile(Path.of(path)))continue;try{if(path.endsWith(".ttc")){var collection=new TrueTypeCollection(new File(path));for(String name:List.of("MicrosoftYaHei","WenQuanYiZenHei","NotoSansCJKsc-Regular")){var ttf=collection.getFontByName(name);if(ttf!=null)return new Font(PDType0Font.load(document,ttf,!(ttf instanceof OpenTypeFont)),collection);}collection.close();}else return new Font(PDType0Font.load(document,new File(path)),null);}catch(IOException|RuntimeException ignored){}}throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"PDF中文字体未配置，请配置hotel.ai.os.pdf.font.sans.path；可导出真实XLSX");}
 private static byte[] pdf(Map<String,Object> data)throws IOException{try(var document=new PDDocument();var font=font(document);var out=new ByteArrayOutputStream();var writer=new Writer(document,font.value())){document.getDocumentInformation().setCustomMetadataValue("reportVersion",data.get("reportVersion").toString());writer.line("财务与经营分析：同源冻结事实",15);for(String key:List.of("reportVersion","periodKind","date","month","status","currency","dateBasis","groupBasis","analysisVersion","analysisStatus","analysisTitle","model"))writer.line(key+"："+data.get(key),9);for(var section:sections(data)){writer.line(section.getKey(),13);if(section.getValue().isEmpty())writer.line("来源尚缺或当前范围无记录，不代表零值。",10);for(var row:section.getValue())for(var entry:row.entrySet())writer.line(entry.getKey()+"："+Objects.toString(entry.getValue(),"资料不足 / 不适用"),9);}writer.closePage();document.save(out);return out.toByteArray();}}
 private static final class Writer implements AutoCloseable{private final PDDocument document;private final PDFont font;private PDPageContentStream stream;private float y;Writer(PDDocument d,PDFont f){document=d;font=f;}void closePage()throws IOException{if(stream!=null){stream.close();stream=null;}}void line(String value,float size)throws IOException{String clean=value.replace('\n',' ').replace('\r',' ').replace('\t',' ');var buffer=new StringBuilder();for(int offset=0;offset<clean.length();){int point=clean.codePointAt(offset);String c=new String(Character.toChars(point));offset+=Character.charCount(point);if(font.getStringWidth(buffer+c)*size/1000>520&&!buffer.isEmpty()){draw(buffer.toString(),size);buffer.setLength(0);}buffer.append(c);}draw(buffer.toString(),size);}void draw(String value,float size)throws IOException{if(stream==null||y<42+size){closePage();var page=new PDPage(PDRectangle.A4);document.addPage(page);stream=new PDPageContentStream(document,page);y=page.getMediaBox().getHeight()-36;}stream.beginText();stream.setFont(font,size);stream.newLineAtOffset(36,y);stream.showText(value);stream.endText();y-=size+5;}public void close()throws IOException{closePage();}}
}
